                        continue
                    # Try Kempe chain swap between target_color and c
                    new_col = kempe_swap(coloring, target_color, c, v)
                    if new_col is None:
                        continue
                    # Validate new coloring
                    if is_valid(new_col):
                        # Check if the swap reduces the number of vertices in target_color
                        if new_col.count(target_color) < coloring.count(target_color):
                            coloring[:] = new_col
                            made_change = True
                            vertices_target = [w for w in range(n) if coloring[w] == target_color]
                            break
            # If no vertices left in target_color, we can reduce color count
            if not any(coloring[v] == target_color for v in range(n)):
                # Shift down higher colors
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                break  # restart from new max color
        return coloring

    # Generate initial colorings from multiple heuristics
    initial_colorings = []
    initial_colorings.append(dsatur())
    initial_colorings.append(welsh_powell())
    initial_colorings.append(smallest_last())
    initial_colorings.append(rlf())

    best_coloring = None
    best_colors = float('inf')
    for coloring in initial_colorings:
        if not is_valid(coloring):
            continue
        num_colors = len(set(coloring))
        if num_colors < best_colors:
            best_colors = num_colors
            best_coloring = coloring[:]
        # Apply local search
        improved = local_search(coloring[:])
        if is_valid(improved):
            num_colors_imp = len(set(improved))
            if num_colors_imp < best_colors:
                best_colors = num_colors_imp
                best_coloring = improved[:]

    # Fallback: if no valid coloring found (should not happen), use greedy
    if best_coloring is None:
        best_coloring = [0] * n
        for i in range(n):
            used = set()
            for u in neighbors[i]:
                if best_coloring[u] != -1:
                    used.add(best_coloring[u])
            c = 0
            while c in used:
                c += 1
            best_coloring[i] = c

    return best_coloring
